/**
 * Data access for the Next.js app.
 *
 * Primary: reads from web/public/data/*.json (committed to repo, works on Vercel).
 * Fallback: reads directly from ../data/wick.db via node:sqlite (local dev only).
 *
 * JSON files are regenerated by `npm run export-json` after each GitHub Actions
 * snapshot run. The fallback path lets local dev work without running the export
 * script after every change.
 */
import { existsSync, readFileSync } from 'node:fs';
import { join } from 'node:path';

export type Cohort = 'gainers_only' | 'both' | 'most_visited_only' | 'trending_only';

export interface CoinEntry {
  cmc_id: number;
  symbol: string;
  name: string;
  slug: string | null;
  price_usd: number | null;
  pct_change_24h: number | null;
  pct_change_1h: number | null;
  volume_24h: number | null;
  fear_greed: number | null;
  cohort: Cohort;
}

export interface LatestSnapshot {
  captured_at: string;
  window_count: number;
  coins: CoinEntry[];
}

export interface CohortStats {
  cohort: Cohort;
  count: number;
  median_T24h: number | null;
  median_T7d: number | null;
  pct_negative_T7d: number | null;
}

export interface EvidenceRow {
  symbol: string;
  name: string;
  captured_at: string;
  endpoint: string;
  price_usd: number | null;
  pct_change_24h: number | null;
  horizon: string | null;
  outcome_price: number | null;
  outcome_pct: number | null;
  source_call: string | null;
}

const DATA_DIR = join(process.cwd(), 'public', 'data');
const LIVE_JSON  = join(DATA_DIR, 'live.json');
const STATS_JSON = join(DATA_DIR, 'stats.json');
const HIST_JSON  = join(DATA_DIR, 'history.json');
const EVI_JSON   = join(DATA_DIR, 'evidence.json');

function readJson<T>(path: string, fallback: T): T {
  try {
    if (!existsSync(path)) return fallback;
    return JSON.parse(readFileSync(path, 'utf8')) as T;
  } catch { return fallback; }
}

export function getLatestSnapshot(): LatestSnapshot | null {
  if (existsSync(LIVE_JSON)) {
    const data = readJson<LatestSnapshot>(LIVE_JSON, { captured_at: '', window_count: 0, coins: [] });
    return data;
  }
  return fromSqlite_getLatestSnapshot();
}

export function getCohortStats(): CohortStats[] {
  if (existsSync(STATS_JSON)) {
    return readJson<CohortStats[]>(STATS_JSON, []);
  }
  return fromSqlite_getCohortStats();
}

export interface HistoryRow {
  captured_at: string;
  total_coins: number;
  fear_greed: number | null;
  signal?: number;
  noise?: number;
  organic?: number;
  trending?: number;
}

export function getSnapshotHistory(): HistoryRow[] {
  if (existsSync(HIST_JSON)) {
    return readJson(HIST_JSON, []);
  }
  return fromSqlite_getSnapshotHistory();
}

export function getEvidence(): EvidenceRow[] {
  if (existsSync(EVI_JSON)) {
    return readJson<EvidenceRow[]>(EVI_JSON, []);
  }
  return fromSqlite_getEvidence();
}

// --- SQLite fallback (local dev only, not available on Vercel) ---

function openSqlite() {
  try {
    const { DatabaseSync } = require('node:sqlite') as typeof import('node:sqlite');
    const DB_PATH = process.env.WICK_DB_PATH ?? join(process.cwd(), '..', 'data', 'wick.db');
    if (!existsSync(DB_PATH)) return null;
    const db = new DatabaseSync(DB_PATH);
    db.exec('PRAGMA journal_mode = WAL');
    return db;
  } catch { return null; }
}

type AppRow = { id: number; cmc_id: number; symbol: string; name: string; slug: string | null; price_usd: number | null; pct_change_24h: number | null; pct_change_1h: number | null; volume_24h: number | null; fear_greed: number | null; endpoint: string };

// eslint-disable-next-line @typescript-eslint/no-explicit-any
function sq<T>(db: NonNullable<ReturnType<typeof openSqlite>>, sql: string, ...args: any[]): T[] {
  return db.prepare(sql).all(...args) as unknown as T[];
}
// eslint-disable-next-line @typescript-eslint/no-explicit-any
function sqOne<T>(db: NonNullable<ReturnType<typeof openSqlite>>, sql: string, ...args: any[]): T | undefined {
  return db.prepare(sql).get(...args) as unknown as T | undefined;
}

function median(values: number[]): number | null {
  if (!values.length) return null;
  const s = [...values].sort((a, b) => a - b);
  const m = Math.floor(s.length / 2);
  return s.length % 2 ? s[m]! : (s[m - 1]! + s[m]!) / 2;
}

function classifySqlite(db: NonNullable<ReturnType<typeof openSqlite>>, captured_at: string): CoinEntry[] {
  const apps = sq<AppRow>(db, `SELECT a.id, a.cmc_id, a.symbol, a.name, a.slug, a.price_usd, a.pct_change_24h, a.pct_change_1h, a.volume_24h, a.fear_greed, a.endpoint FROM appearances a JOIN snapshots s ON s.id = a.snapshot_id WHERE s.captured_at = ?`, captured_at);
  const gainers = new Map<number, AppRow>();
  const mv = new Map<number, AppRow>();
  const trending = new Map<number, AppRow>();
  for (const a of apps) {
    if (a.endpoint === 'gainers') gainers.set(a.cmc_id, a);
    else if (a.endpoint === 'most_visited') mv.set(a.cmc_id, a);
    else if (a.endpoint === 'trending') trending.set(a.cmc_id, a);
  }
  const coins: CoinEntry[] = [];
  for (const cmc_id of new Set([...gainers.keys(), ...mv.keys(), ...trending.keys()])) {
    const inG = gainers.has(cmc_id), inMV = mv.has(cmc_id);
    const cohort: Cohort = inG && inMV ? 'both' : inG ? 'gainers_only' : inMV ? 'most_visited_only' : 'trending_only';
    const p = gainers.get(cmc_id) ?? mv.get(cmc_id) ?? trending.get(cmc_id)!;
    coins.push({ cmc_id, symbol: p.symbol, name: p.name, slug: p.slug ?? null, price_usd: p.price_usd, pct_change_24h: p.pct_change_24h, pct_change_1h: p.pct_change_1h, volume_24h: p.volume_24h, fear_greed: p.fear_greed, cohort });
  }
  const order: Record<Cohort, number> = { both: 0, gainers_only: 1, most_visited_only: 2, trending_only: 3 };
  return coins.sort((a, b) => order[a.cohort] - order[b.cohort]);
}

function fromSqlite_getLatestSnapshot(): LatestSnapshot | null {
  const db = openSqlite();
  if (!db) return null;
  type W = { captured_at: string };
  const latest = sqOne<W>(db, `SELECT captured_at FROM snapshots ORDER BY captured_at DESC LIMIT 1`);
  if (!latest) return { captured_at: '', window_count: 0, coins: [] };
  const countRow = sqOne<{ n: number }>(db, `SELECT COUNT(DISTINCT captured_at) as n FROM snapshots`);
  return { captured_at: latest.captured_at, window_count: countRow?.n ?? 0, coins: classifySqlite(db, latest.captured_at) };
}

function fromSqlite_getCohortStats(): CohortStats[] {
  const db = openSqlite();
  if (!db) return [];
  type W = { captured_at: string };
  const windows = sq<W>(db, `SELECT DISTINCT captured_at FROM snapshots`);
  const data = new Map<Cohort, { t24h: number[]; t7d: number[]; count: number }>();
  for (const c of ['gainers_only', 'both', 'most_visited_only', 'trending_only'] as Cohort[]) data.set(c, { t24h: [], t7d: [], count: 0 });
  type Slim = { id: number; cmc_id: number; endpoint: string };
  type Out = { horizon: string; pct_change: number | null };
  for (const { captured_at } of windows) {
    const apps = sq<Slim>(db, `SELECT a.id, a.cmc_id, a.endpoint FROM appearances a JOIN snapshots s ON s.id=a.snapshot_id WHERE s.captured_at=?`, captured_at);
    const gIds = new Set(apps.filter(a => a.endpoint === 'gainers').map(a => a.cmc_id));
    const mvIds = new Set(apps.filter(a => a.endpoint === 'most_visited').map(a => a.cmc_id));
    for (const cmc_id of new Set(apps.map(a => a.cmc_id))) {
      const inG = gIds.has(cmc_id), inMV = mvIds.has(cmc_id);
      const cohort: Cohort = inG && inMV ? 'both' : inG ? 'gainers_only' : inMV ? 'most_visited_only' : 'trending_only';
      const d = data.get(cohort)!;
      d.count++;
      const pep = inG ? 'gainers' : inMV ? 'most_visited' : 'trending';
      const app = apps.find(a => a.cmc_id === cmc_id && a.endpoint === pep);
      if (!app) continue;
      for (const o of sq<Out>(db, `SELECT horizon, pct_change FROM outcomes WHERE appearance_id=? AND pct_change IS NOT NULL`, app.id)) {
        if (o.pct_change == null) continue;
        if (o.horizon === 'T24h') d.t24h.push(o.pct_change);
        if (o.horizon === 'T7d') d.t7d.push(o.pct_change);
      }
    }
  }
  return (['gainers_only', 'both', 'most_visited_only', 'trending_only'] as Cohort[]).map(cohort => {
    const d = data.get(cohort)!;
    return { cohort, count: d.count, median_T24h: median(d.t24h), median_T7d: median(d.t7d), pct_negative_T7d: d.t7d.length ? (d.t7d.filter(v => v < 0).length / d.t7d.length) * 100 : null };
  });
}

function fromSqlite_getSnapshotHistory() {
  const db = openSqlite();
  if (!db) return [];
  type H = { captured_at: string; total_coins: number; fear_greed: number | null };
  return sq<H>(db, `SELECT s.captured_at, COUNT(DISTINCT a.cmc_id) as total_coins, AVG(a.fear_greed) as fear_greed FROM (SELECT DISTINCT captured_at FROM snapshots ORDER BY captured_at DESC LIMIT 48) s LEFT JOIN appearances a ON a.snapshot_id IN (SELECT id FROM snapshots WHERE captured_at = s.captured_at) GROUP BY s.captured_at ORDER BY s.captured_at DESC`);
}

function fromSqlite_getEvidence(): EvidenceRow[] {
  const db = openSqlite();
  if (!db) return [];
  return sq<EvidenceRow>(db, `
    SELECT a.symbol, a.name, s.captured_at, a.endpoint,
      a.price_usd, a.pct_change_24h,
      o.horizon, o.price_usd as outcome_price, o.pct_change as outcome_pct, o.source_call
    FROM appearances a
    JOIN snapshots s ON s.id = a.snapshot_id
    LEFT JOIN outcomes o ON o.appearance_id = a.id
    ORDER BY s.captured_at DESC, a.symbol ASC
    LIMIT 500
  `);
}
